CREATE PROCEDURE "informix".sp_ctedigital_validaclientes(pNumcte CHAR(20), pIdentificador CHAR(1), pSistema CHAR(1))

--RETORNOS -> NO HAY YA QUE SE EJECUTA DESDE UN TRIGGER

/*
-DESCRIPCIÓN: PROCEDIMIENTO QUE ES MANDADO LLAMAR DESDE LOS TRIGERS si_tr_ctedigital, sd_tr_ctedigital, sc_tr_ctedigital
	identificando asi el origen de la asignacion de tarjeta
-FECHA DE MODIFICACION: 20 DE ENERO DE 2014',
-BASE DE DATOS: BDINTEG
-MODIFICA: RIGOBERTO GONZALEZ
*/

--DECLARACION DE VARIABLES--
DEFINE iSql_err		    INTEGER; 
DEFINE cCodret		    CHAR(6); --SE DEJA LA VARIABLE A PESAR DE NO REGRESARSE PARA QUE SEA DE UTILIDAD EN EL ARCHIVO DEBUG
DEFINE cNumcteBanco     CHAR(20);
DEFINE iEstatus_Envio   INTEGER;
DEFINE cEmail           CHAR(100);
DEFINE cTelefono        CHAR(13);
DEFINE cNumcteCoppel    CHAR(20);
DEFINE dtFechaHoy       DATE;
DEFINE cInsertaError    CHAR(1); --DSB20220815
DEFINE cObservs         CHAR(100); --DSB20220815
DEFINE isam_err         SMALLINT; --DSB20220815
DEFINE error_info       CHAR(100); --DSB20220815

--INICIALIZACION DE VARIABLES--
LET iSql_err		     = 0;
LET cCodret		         = '000000';
LET cNumcteBanco         = '';
LET iEstatus_Envio       = 0;
LET cEmail               = '';
LET cTelefono            = '';
LET cNumcteCoppel        = '';
LET dtFechaHoy           = DATE(1);
LET cObservs             = 'INICIA'; --DSB20220815
LET cInsertaError        = ''; --DSB20220815
--INICIO--
BEGIN
	--CONTROL DE ERRORES--
	ON EXCEPTION SET iSql_err,isam_err,error_info  --DSB20220815
	  
		IF iSql_err <> 0 THEN
		    IF cInsertaError = '1' THEN --INICIA DSB20220815
				INSERT INTO "informix".si_bitdemctedig(numcte,sistema,error,observaciones,fecha_insert) 
				VALUES (pNumcte,pIdentificador||'|'||pSistema,iSql_err,TRIM(cObservs)||'|'||isam_err||'|'||error_info,CURRENT); 		  
			END IF;	--TERMINA DSB20220815			
				LET cCodret = iSql_err;		
				RETURN ;
		END IF;
	END EXCEPTION;
	
	 ON EXCEPTION IN (1) --INICIA DSB20220815
		IF cInsertaError = '1' THEN 
			 INSERT INTO "informix".si_bitdemctedig(numcte,sistema,error,observaciones,fecha_insert) 
			 VALUES (pNumcte,pIdentificador||'|'||pSistema,cCodret,TRIM(cObservs),CURRENT); 
		END IF; 
	 END EXCEPTION WITH RESUME; --TERMINA DSB20220815
	
		
	--SET DEBUG FILE TO '/tmp/cyrv/sp_ctedigital_validaclientes.out';
	--TRACE ON;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	SELECT TRIM(valor) --INICIA DSB20220815
	INTO cInsertaError
	FROM bdinteg:"informix".si_param
	WHERE cod_param='512'; --TERMINA DSB20220815

	----------------CONTROL DE ERRORES POR PARAMETRO----------

	IF NVL(pNumcte,'') = '' OR NVL(pIdentificador,'') = '' THEN
		LET cObservs = TRIM('PASO 1: 000001 EN VALIDACION DE PARAMETROS pNumcte O pIdentificador'); --DSB20220815		
		LET cCodret = '000001'; --ALGUNO DE LOS PARAMETROS ESTA VACIO O NULO
		RAISE EXCEPTION 1,0,''; --DSB20220815		
		RETURN ;
	END IF;
		
	IF NVL(pIdentificador,'') NOT IN ('1','2') THEN
		LET cObservs = TRIM('PASO 1.1: 000002 EN VALIDACION DE PARAMETRO pIdentificador'); --DSB20220815
		LET cCodret = '000002'; --IDENTIFICADOR DE ORIGEN NO VALIDO
		RAISE EXCEPTION 1,0,'';
		RETURN ;
	END IF;
	
	IF NVL(pSistema,'') NOT IN ('1','2','3') THEN
		LET cObservs = TRIM('PASO 1.2: 000002 EN VALIDACION DE PARAMETRO pSistema'); --DSB20220815
		LET cCodret = '000002'; --IDENTIFICADOR DE ORIGEN NO VALIDO
		RAISE EXCEPTION 1,0,''; --DSB20220815
		RETURN ;
	END IF;
	  
		--************************************************************************************
		---------------****************BLOQUE DE CONSULTA*************************************
		--************************************************************************************
	 	
		--SE VERIFICA SI EXISTE EL CLIENTE EN LA TABLA
		LET cObservs = TRIM('PASO 2: Al CONSULTAR TABLA si_clientes_digital'); --DSB20220815
		SELECT num_cte_banco, estatus_envio
		INTO cNumcteBanco , iEstatus_Envio
		FROM "informix".si_clientes_digital
		WHERE consecutivo = (SELECT MAX(consecutivo) AS maxcons FROM "informix".si_clientes_digital WHERE 	consecutivo = consecutivo AND num_cte_banco = TRIM(pNumcte) AND num_cte_coppel = num_cte_coppel)
		AND num_cte_banco = TRIM(pNumcte) --PARAMETRO
		AND num_cte_coppel = num_cte_coppel;
		
		IF cNumcteBanco IS NULL or cNumcteBanco = '' THEN
		LET cObservs = TRIM('PASO 3: Al CONSULTAR TABLA si_clientes_digital_old'); --DSB20220815
				SELECT num_cte_banco, estatus_envio
				INTO cNumcteBanco , iEstatus_Envio
				FROM "informix".si_clientes_digital_old
				WHERE consecutivo = (SELECT MAX(consecutivo) AS maxcons FROM "informix".si_clientes_digital_old WHERE 	consecutivo = consecutivo AND num_cte_banco = TRIM(pNumcte) AND num_cte_coppel = num_cte_coppel)
				AND num_cte_banco = TRIM(pNumcte) --PARAMETRO
				AND num_cte_coppel = num_cte_coppel;
		END IF;
		
		
		
		/*
		SI EXISTE Y ESTA CON ESTATUS NULL, 1, 2 o 4, Donde:
		NULL = Trama no generada
		1 = Guardado Exitoso/Correo guardado/Actualización correcta.
		2 = El correo que ingreso ya se encuentra asociado con otro cliente, favor de enviar un SA a correosecommercev2.
		4 = El cliente ya cuenta con un correo registrado.
		5 = No procesado
		*/
		
		IF cNumcteBanco IS NOT NULL AND (iEstatus_Envio IS NULL OR iEstatus_Envio IN (1,2,4,5) )THEN 
			LET cObservs = TRIM('PASO 4: 000004 EN VALIDACION DE: cNumcteBanco O iEstatus_Envio'); --DSB20220815
			--TERMINA EJECUCION DEL PROCEDIMIENTO
			LET cCodret = '000004'; --NO SE REALIZO LA INSERCION
			RAISE EXCEPTION 1,0,''; --DSB20220815
			RETURN ;
			
		/*
		0 = No se pudo actualizar el cliente/Solo se permite deshabilitar este FLAG en este origen/No se pudo actualizar el FLAG.
		3 = Error al generar XML
		6 = Correo no válido.
		7 = Falló al actualizar indicadores.
		8 = No se encontró correo, no se puede actualizar/No se encontró correo para ese tipo de cliente,no se puede actualizar flag.
		10= El correo ya cuenta con cuenta activa en coppel.com por otro cliente.
		*/
		-- ENTRANDO SI EL CLIENTE NO ESTA EN LA TABLA PRINCIPAL O SI SU ESTATUS ES 3 O 5
		ELIF cNumcteBanco IS NULL OR iEstatus_Envio IN (0,3,6,7,8,10) THEN
		
			--SE VERIFICA SI EL CLIENTE BANCO TIENE ASOCIADO UN CLIENTE COPPEL	
			LET cObservs = TRIM('PASO 5: Al CONSULTAR TABLA : si_cliente 1ER LLAMADO'); --DSB20220815
			SELECT NVL(numcte_ref,'')
			INTO cNumcteCoppel
			FROM "informix".si_cliente
			WHERE empresa = '001'
			AND numcte = TRIM(pNumcte);			
			
			--SE VERIFICA SI EL CLIENTE TIENE CORREO O CELULAR VALIDOS
			LET cObservs = TRIM('PASO 6: Al CONSULTAR TABLA : si_correos 1ER LLAMADO'); --DSB20220815
			SELECT NVL(correo_elec,'') AS correo
			INTO cEmail
			FROM "informix".si_correos mail 
			WHERE empresa = '001'
			AND numcte = TRIM(pNumcte) 
			AND status_correo = 'A'; --ACTIVO			
			
			--SE VERIFICA SI EL CLIENTE TIENE TELEFONO VALIDO
			LET cObservs = TRIM('PASO 7: Al CONSULTAR TABLA : si_telefonos_actual 1ER LLAMADO'); --DSB20220815
			SELECT NVL(telefono,'') AS telefono
			INTO cTelefono
			FROM "informix".si_telefonos_actual 
			WHERE empresa = '001' 
			AND numcte = TRIM(pNumcte) 
			AND tipo_tel = 2  --CELULAR
			AND cofetel = 'V'; --VALIDO POR COFETEL
			
			
			--SE VERIFICA QUE HAYA ENCONTRADO AL MENOS UNO DE LOS DOS DATOS
			IF cNumcteBanco IS NULL THEN
				IF 	NVL(cEmail,'') = '' AND NVL(cTelefono,'') = '' THEN		
						LET iEstatus_Envio = 0; --SE INICIALIZA LA VARIABLE
						LET iEstatus_Envio = 3; --CLIENTE SIN CORREO Y CELULAR VALIDO	
				ELIF NVL(cEmail,'') <> '' OR NVL(cTelefono,'') <> '' THEN		
						LET iEstatus_Envio = 0; --SE INICIALIZA LA VARIABLE
						LET iEstatus_Envio = NULL; --TRAMA NO GENERADA
				END IF;
			ELSE --cNumcteBanco IS NOT NULL
				IF 	NVL(cEmail,'') = '' AND NVL(cTelefono,'') = '' THEN
						LET cObservs = TRIM('PASO 8: 000003 EN VALIDACION DE: cEmail Y cTelefono 1ER LLAMADO');	--DSB20220815			
						LET cCodret = '000003'; --CORREO Y CELULAR INVALIDOS
						RAISE EXCEPTION 1,0,''; --DSB20220815
						RETURN ;
				ELIF NVL(cEmail,'') <> '' OR NVL(cTelefono,'') <> '' THEN		
						LET iEstatus_Envio = 0; --SE INICIALIZA LA VARIABLE
						LET iEstatus_Envio = NULL; --TRAMA NO GENERADA
				END IF;
				
			END IF;
			
			--2 = TRAMA RECIBIDA SATISFACTORIAMENTE
		ELIF cNumcteBanco IS NOT NULL AND iEstatus_Envio = 2 THEN 
			--SE VERIFICA SI EL CLIENTE BANCO TIENE ASOCIADO UN CLIENTE COPPEL	
			LET cObservs = TRIM('PASO 9: Al CONSULTAR TABLA : si_cliente 2DO LLAMADO'); --DSB20220815
			SELECT NVL(numcte_ref,'')
			INTO cNumcteCoppel
			FROM "informix".si_cliente
			WHERE empresa = '001'
			AND numcte = TRIM(pNumcte);
			
			--SI NO TIENE ASOCIADO NINGUN NUMERO
			IF NVL(cNumcteCoppel,'') = '' THEN
				LET cObservs = TRIM('PASO 10: 000004 EN VALIDACION DE: cNumcteCoppel'); --DSB20220815
				LET cCodret = '000004'; --NO SE REALIZO LA INSERCION
				RAISE EXCEPTION 1,0,''; --DSB20220815
				RETURN ;
			END IF;
			
			--SE VERIFICA SI EL CLIENTE TIENE CORREO O CELULAR VALIDOS
			LET cObservs = TRIM('PASO 11: Al CONSULTAR TABLA : si_correos 2DO LLAMADO'); --DSB20220815
			SELECT NVL(correo_elec,'') AS correo
			INTO cEmail
			FROM "informix".si_correos mail 
			WHERE empresa = '001'
			AND numcte = TRIM(pNumcte) 
			AND status_correo = 'A'; --ACTIVO
			
			LET cObservs = TRIM('PASO 12: Al CONSULTAR TABLA : si_telefonos_actual 2DO LLAMADO'); --DSB20220815
			SELECT NVL(telefono,'') AS telefono
			INTO cTelefono
			FROM "informix".si_telefonos_actual 
			WHERE empresa = '001' 
			AND numcte = TRIM(pNumcte) 
			AND tipo_tel = 2  --CELULAR
			AND cofetel = 'V'; --VALIDO POR COFETEL
			
			--SI NO TIENE CORREO NI CELULAR VALIDOS
			IF NVL(cEmail,'') = '' AND NVL(cTelefono,'') = '' THEN
				LET cObservs = TRIM('PASO 13: 000003 EN VALIDACION DE: cEmail Y cTelefono'); --DSB20220815
				LET cCodret = '000003'; --CORREO Y CELULAR INVALIDOS
				RAISE EXCEPTION 1,0,''; --DSB20220815
				RETURN ;
			END IF;
			
			--SI TIENE CORREO Y CELULAR VALIDO HACE LA ASIGNACION DEL ESTATUS ENVIO CORRESPONDIENTE
			LET iEstatus_Envio = 0; --SE INICIALIZA LA VARIABLE
			LET iEstatus_Envio = NULL; --trama no generada
		
		ELSE 
			--SI NO CAE EN NINGUNO DE LOS FLUJOS ANTERIORES	
			LET cObservs = TRIM('PASO 14: 000004 SINO SE CUMPLE NINGUNO DE LOS FLUJOS ANTERIORES'); --DSB20220815			
			LET cCodret = '000004'; --NO SE REALIZO LA INSERCION
			RAISE EXCEPTION 1,0,''; --DSB20220815
			RETURN ;
			
		END IF;

		---***************************************************
		--SE CONSULTA LA FECHA HOY DE LA TABLA DE FECHAS PERTENECIENTE A LA BASE DE DATOS DEL SP PARA LA INSERCION POSTERIOR
		LET cObservs = TRIM('PASO 15: Al CONSULTAR TABLA : si_fechas'); --DSB20220815
		SELECT fecha_hoy
		INTO dtFechaHoy
		FROM "informix".si_fechas
		WHERE empresa = '001';
				
		INSERT INTO "informix".si_clientes_digital (num_cte_banco, num_cte_coppel, xml, estatus_envio, error, identificador, sistema, fecha_insert) VALUES (TRIM(pNumcte), NVL(cNumcteCoppel,''), '',iEstatus_Envio,'',pIdentificador, pSistema, dtFechaHoy);
		
		--SE VALIDA QUE SE HAYA HECHO CORRECTAMENTE EL INSERT
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cObservs = TRIM('PASO 16: AL REALIZAR LA INSERCION A LA TABLA:  si_clientes_digital'); --DSB20220815
			LET cCodret = '000004'; --NO SE REALIZO LA INSERCION
			RAISE EXCEPTION 1,0,''; --DSB20220815
			RETURN ;
		END IF;
	
		---RETURN GENERAL
		RETURN ;		
	
END;
END PROCEDURE
