create view "informix".sd_movconta_view (empresa,fecha_mov,num_producto,sistema,transacc,monto,cuantos) as 
  select x0.empresa ,x0.fecha_mov ,x0.num_producto ,'06' ,x1.transacc 
    ,sum(x0.monto ) ,count(*) from bdicred:"informix".sd_movdia 
    x0 ,bdicred:"informix".sd_transfun x1 where ((((x1.empresa 
    = x0.empresa ) AND (x1.codigo_fun = x0.codigo_fun ) ) AND 
    (x1.codigo_ref = x0.codigo_ref ) ) AND (x0.reversado = 'N'
     ) ) group by x0.empresa ,x0.fecha_mov ,x0.num_producto ,
    x1.transacc ;                                
create view "informix".vi_empleado_ofi (ejecutivo,nombre,sucursal,puesto) as 
  select x0.ejecutivo ,x0.nombre ,x0.sucursal ,x0.puesto from 
    "informix".si_ejecut x0 where ((((x0.nombre != 'USUARIO DE SISTEMA'
     ) AND (x0.ejecutivo != ALL (select x1.ejecutivo from "informix"
    .si_perfil_ejecut x1 ) ) ) AND (x0.sucursal = ANY (select 
    x2.id_ptf from "informix".si_ptf x2 where (x2.tipo = 'S' ) 
    ) ) ) AND (x0.password != 'BAJA' ) ) order by 3 ,4 ;      
                                                             
                
create view "informix".bld_registered (bld_id) as 
  select x0.bld_id from "informix".sysbldregistered x0 ;       
                                                             
                                                             
                                   
create view "informix".bldi_required (bldi_id,bld_id) as 
  select x0.bldi_id ,x0.bld_id from "informix".sysbldirequired 
    x0 ;                                                     
                                                             
                            
create view "informix".bldi_provided (bldi_id,bld_id) as 
  select x0.bldi_id ,x0.bld_id from "informix".sysbldiprovided 
    x0 ;                                                     
                                                             
                            

