create trigger "informix".tr_si_empresas_insert insert on "informix"
    .si_empresas referencing new as nvo
    for each row
        (
        insert into bdinteg@coppelcont_tcp:"informix".si_empresas 
    (empresa,razon_social,rfc,domicilio_fiscal,codigo_postal,pais,estado,
    ciudad,telefono1,telefono2,fax_1,fax_2,rep_legal,actividad_principa,
    sector,user_insert,fecha_insert)  values (nvo.empresa ,nvo.razon_social 
    ,nvo.rfc ,nvo.domicilio_fiscal ,nvo.codigo_postal ,nvo.pais ,nvo.estado 
    ,nvo.ciudad ,nvo.telefono1 ,nvo.telefono2 ,nvo.fax_1 ,nvo.fax_2 ,
    nvo.rep_legal ,nvo.actividad_principa ,nvo.sector ,nvo.user_insert 
    ,nvo.fecha_insert ));

create trigger "informix".tr_si_empresas_update update on "informix"
    .si_empresas referencing old as ant new as nvo
    for each row
        (
        update bdinteg@coppelcont_tcp:"informix".si_empresas 
    set bdinteg@coppelcont_tcp:"informix".si_empresas.empresa = nvo.empresa 
    ,bdinteg@coppelcont_tcp:"informix".si_empresas.razon_social = nvo.razon_social 
    ,bdinteg@coppelcont_tcp:"informix".si_empresas.rfc = nvo.rfc ,bdinteg@coppelcont_tcp:
    "informix".si_empresas.domicilio_fiscal = nvo.domicilio_fiscal ,bdinteg@coppelcont_tcp:
    "informix".si_empresas.codigo_postal = nvo.codigo_postal ,bdinteg@coppelcont_tcp:
    "informix".si_empresas.pais = nvo.pais ,bdinteg@coppelcont_tcp:"informix"
    .si_empresas.estado = nvo.estado ,bdinteg@coppelcont_tcp:"informix"
    .si_empresas.ciudad = nvo.ciudad ,bdinteg@coppelcont_tcp:"informix"
    .si_empresas.telefono1 = nvo.telefono1 ,bdinteg@coppelcont_tcp:"informix"
    .si_empresas.telefono2 = nvo.telefono2 ,bdinteg@coppelcont_tcp:"informix"
    .si_empresas.fax_1 = nvo.fax_1 ,bdinteg@coppelcont_tcp:"informix".si_empresas.fax_2 
    = nvo.fax_2 ,bdinteg@coppelcont_tcp:"informix".si_empresas.rep_legal 
