create trigger "informix".tr_del_si_prodtran delete on "informix"
    .si_prodtran referencing old as o
    for each row
        when ((((((((TRIM ( BOTH  ' ' FROM o.c_ccmayor ) || TRIM 
    ( BOTH  ' ' FROM o.c_ccsub ) ) || TRIM ( BOTH  ' ' FROM o.c_ccsubsub 
    ) ) || TRIM ( BOTH  ' ' FROM o.c_ccsssub ) ) || TRIM ( BOTH  ' ' FROM 
    o.c_ccssssub ) ) || TRIM ( BOTH  ' ' FROM o.c_sector ) ) = '95120400000000'
     ) OR ((((((TRIM ( BOTH  ' ' FROM o.a_ccmayor ) || TRIM ( BOTH  ' '
     FROM o.a_ccsub ) ) || TRIM ( BOTH  ' ' FROM o.a_ccsubsub ) ) || TRIM 
    ( BOTH  ' ' FROM o.a_ccsssub ) ) || TRIM ( BOTH  ' ' FROM o.a_ccssssub 
    ) ) || TRIM ( BOTH  ' ' FROM o.a_sector ) ) = '95120400000000' ) ) 
    )
            (
            delete from bdicont@coppelcont_tcp:"informix".co_conc_usertran 
     where ((((empresa = o.empresa ) AND (sistema = o.sistema ) ) AND (tran_ctral 
    = o.transaccion ) ) AND (usuario = 'credito' ) ) );

create trigger "informix".tr_ins_si_prodtran insert on "informix"
    .si_prodtran referencing new as nvo
    for each row
        when (((((((((TRIM ( BOTH  ' ' FROM nvo.c_ccmayor ) || 
    TRIM ( BOTH  ' ' FROM nvo.c_ccsub ) ) || TRIM ( BOTH  ' ' FROM nvo.c_ccsubsub 
    ) ) || TRIM ( BOTH  ' ' FROM nvo.c_ccsssub ) ) || TRIM ( BOTH  ' ' 
    FROM nvo.c_ccssssub ) ) || TRIM ( BOTH  ' ' FROM nvo.c_sector ) ) 
    = '95120400000000' ) OR ((((((TRIM ( BOTH  ' ' FROM nvo.a_ccmayor ) 
    || TRIM ( BOTH  ' ' FROM nvo.a_ccsub ) ) || TRIM ( BOTH  ' ' FROM nvo.a_ccsubsub 
    ) ) || TRIM ( BOTH  ' ' FROM nvo.a_ccsssub ) ) || TRIM ( BOTH  ' ' 
    FROM nvo.a_ccssssub ) ) || TRIM ( BOTH  ' ' FROM nvo.a_sector ) ) 
    = '95120400000000' ) ) AND ((select count(*) from bdicont@coppelcont_tcp:
    "informix".co_conc_usertran x0 where ((((x0.empresa = nvo.empresa 
    ) AND (x0.sistema = nvo.sistema ) ) AND (x0.tran_ctral = nvo.transaccion 
    ) ) AND (x0.usuario = 'credito' ) ) ) = 0 ) ) )
            (
            insert into bdicont@coppelcont_tcp:"informix".co_conc_usertran 
    (empresa,sistema,usuario,secuencia,tran_suc,tran_ctral,conc_user,conc_tran,
    tipo_mov,fecha_alta,fecha_modif,user_modif)  values (nvo.empresa ,nvo.sistema 
    ,'credito' ,'1' ,'600' ,nvo.transaccion ,'S' ,'S' ,'A' ,CURRENT year to fraction(3) 
    ,CURRENT year to fraction(3) ,'informix' ));

create trigger "informix".tr_upd_si_prodtran update on "informix"
    .si_prodtran referencing old as o new as nvo
    for each row
        when ((((((((TRIM ( BOTH  ' ' FROM nvo.c_ccmayor ) || 
    TRIM ( BOTH  ' ' FROM nvo.c_ccsub ) ) || TRIM ( BOTH  ' ' FROM nvo.c_ccsubsub 
    ) ) || TRIM ( BOTH  ' ' FROM nvo.c_ccsssub ) ) || TRIM ( BOTH  ' ' 
    FROM nvo.c_ccssssub ) ) || TRIM ( BOTH  ' ' FROM nvo.c_sector ) ) 
    = '95120400000000' ) OR ((((((TRIM ( BOTH  ' ' FROM nvo.a_ccmayor ) 
    || TRIM ( BOTH  ' ' FROM nvo.a_ccsub ) ) || TRIM ( BOTH  ' ' FROM nvo.a_ccsubsub 
    ) ) || TRIM ( BOTH  ' ' FROM nvo.a_ccsssub ) ) || TRIM ( BOTH  ' ' 
    FROM nvo.a_ccssssub ) ) || TRIM ( BOTH  ' ' FROM nvo.a_sector ) ) 
