            insert into bdmis:"informix".mi_sucursalesinfo (empresa,
    num_sucursal,tipo_suc,nombre,direccion1,direccion2,telefono,num_plaza,
    promotor_virtual)  values ('001' ,new.sucursal ,'0' ,new.nombre ,new.direccion1 
