create trigger "informix".tr_telefonos_insert insert on "informix"
    .si_telefonos referencing new as nvo
    for each row
        (
        --- empresa
        --- no. cliente
        --- telefono
        --- tipo de telefono
        --- status
        --- secuencia
        --- extension
        --- carrier
        --- canal
        --- contacto
        --- cofetel
        --- fecha y hora de registro
        execute procedure "informix".sp_tel_actual(nvo.empresa 
    ,nvo.numcte ,nvo.telefono ,nvo.tipo_tel ,nvo.status_tel ,nvo.secuencia 
    ,nvo.extension ,nvo.carrier ,nvo.canal ,nvo.contacto ,nvo.cofetel 
    ,nvo.fecha_hora ,nvo.user_insert ));

create trigger "informix".tr_telefonos_update update of status_stel 
    on "informix".si_telefonos referencing new as upd
    for each row
        (
        update "informix".si_telefonos_actual set "informix".si_telefonos_actual.status_stel 
    = upd.status_stel  where ((upd.numcte = numcte ) AND (upd.secuencia 
    = secuencia ) ) );

create trigger "informix".tr_tel_conf_ivr_update update of tel_confirmado 
    on "informix".si_telefonos referencing new as x1
    for each row
        (
        update "informix".si_telefonos_actual set "informix".si_telefonos_actual.tel_confirmado 
    = x1.tel_confirmado ,"informix".si_telefonos_actual.fech_confirmado 
    = x1.fech_confirmado  where ((numcte = x1.numcte ) AND (telefono 
    = x1.telefono ) ) );

