create trigger "informix".tr_si_fechas_insert insert on "informix"
    .si_fechas referencing new as nvo
    for each row
        (
        insert into bdinteg@coppelcont_tcp:"informix".si_fechas 
    (empresa,fecha_hoy,fecha_ant,prox_fecha,pri_dia_mes,pri_hab_mes,ult_dia_mes,
    ult_hab_mes,user_insert,fecha_insert)  values (nvo.empresa ,nvo.fecha_hoy 
