    ,nvo.ult_dia_mes ,nvo.ult_hab_mes ,nvo.user_insert ,nvo.fecha_insert 
    ));

create trigger "informix".tr_si_fechas_delete delete on "informix"
    .si_fechas referencing old as ant
    for each row
        (
        delete from bdinteg@coppelcont_tcp:"informix".si_fechas 
     where ((((((((((empresa = ant.empresa ) AND (fecha_hoy = ant.fecha_hoy 
    ) ) AND (fecha_ant = ant.fecha_ant ) ) AND (prox_fecha = ant.prox_fecha 
    ) ) AND (pri_dia_mes = ant.pri_dia_mes ) ) AND (pri_hab_mes = ant.pri_hab_mes 
    ) ) AND (ult_dia_mes = ant.ult_dia_mes ) ) AND (ult_hab_mes = ant.ult_hab_mes 
    ) ) AND (user_insert = ant.user_insert ) ) AND (fecha_insert = ant.fecha_insert 
    ) ) );

