    ,nuevo.empleado ,nuevo.fecha_insert ,nuevo.fecha_modificacion ,CURRENT 
    year to fraction(3) ));

create trigger "informix".tr_llenado_bitacora_ptf update on "informix"
    .si_ptf referencing old as ant new as nvo
    for each row
        when ((ant.tipo != nvo.tipo ) )
            (
            --tipo
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'tipo' ,ant.tipo ,nvo.tipo )),
    
        when ((ant.clave_sit != nvo.clave_sit ) )
            (
            --clave_sit
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'clave_sit' ,ant.clave_sit ,nvo.clave_sit 
    )),
        when ((ant.fecha_sit != nvo.fecha_sit ) )
            (
            --fecha_sit
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'fecha_sit' ,ant.fecha_sit ,nvo.fecha_sit 
    )),
        when ((ant.cve_pais != nvo.cve_pais ) )
            (
            --cve_pais
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_pais' ,ant.cve_pais ,nvo.cve_pais 
    )),
        when ((ant.calle != nvo.calle ) )
            (
            --calle
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'calle' ,ant.calle ,nvo.calle 
    )),
        when ((ant.num_ext != nvo.num_ext ) )
            (
            --num_ext
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'num_ext' ,ant.num_ext ,nvo.num_ext 
    )),
        when ((ant.num_int != nvo.num_int ) )
            (
            --num_int
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'num_int' ,ant.num_int ,nvo.num_int 
    )),
        when ((ant.cve_col != nvo.cve_col ) )
            (
            --cve_col
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_col' ,ant.cve_col ,nvo.cve_col 
    )),
        when ((ant.cve_mun != nvo.cve_mun ) )
            (
            --cve_mun
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_mun' ,ant.cve_mun ,nvo.cve_mun 
    )),
        when ((ant.cve_localidad != nvo.cve_localidad ) )
            (
            --cve_localidad
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_localidad' ,ant.cve_localidad 
    ,nvo.cve_localidad )),
        when ((ant.cp != nvo.cp ) )
            (
            --cp
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cp' ,ant.cp ,nvo.cp )),
        when ((ant.cve_ciudad != nvo.cve_ciudad ) )
            (
            --cve_ciudad
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_ciudad' ,ant.cve_ciudad ,
    nvo.cve_ciudad )),
        when ((ant.cve_estado != nvo.cve_estado ) )
            (
            --cve_estado
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'cve_estado' ,ant.cve_estado ,
    nvo.cve_estado )),
        when ((ant.latitud != nvo.latitud ) )
            (
            --latitud
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'latitud' ,ant.latitud ,nvo.latitud 
    )),
        when ((ant.longitud != nvo.longitud ) )
            (
            --longitud
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'longitud' ,ant.longitud ,nvo.longitud 
    )),
        when ((ant.tel1 != nvo.tel1 ) )
            (
            --tel1
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'tel1' ,ant.tel1 ,nvo.tel1 )),
    
        when ((ant.tel2 != nvo.tel2 ) )
            (
            --tel2
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'tel2' ,ant.tel2 ,nvo.tel2 )),
    
        when ((ant.referencia != nvo.referencia ) )
            (
            --referencia
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'referencia' ,ant.referencia ,
    nvo.referencia )),
        when ((ant.tipo_bovsuc != nvo.tipo_bovsuc ) )
            (
            --tipo_bovsuc
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'tipo_bovsuc' ,ant.tipo_bovsuc 
    ,nvo.tipo_bovsuc )),
        when ((ant.correo != nvo.correo ) )
            (
            --correo
