    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'correo' ,ant.correo ,nvo.correo 
    )),
        when ((ant.horario != nvo.horario ) )
            (
            --horario
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'horario' ,ant.horario ,nvo.horario 
    )),
        when ((ant.servicio_canje != nvo.servicio_canje ) )
            (
            --servicio_canje
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'servicio_canje' ,ant.servicio_canje 
    ,nvo.servicio_canje )),
        when ((ant.tipo_acceso != nvo.tipo_acceso ) )
            (
            --tipo_acceso
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'tipo_acceso' ,ant.tipo_acceso 
    ,nvo.tipo_acceso )),
        when ((ant.dispensa_baja != nvo.dispensa_baja ) )
            (
            --dispensa_baja
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'dispensa_baja' ,ant.dispensa_baja 
    ,nvo.dispensa_baja )),
        when ((ant.com_retiro != nvo.com_retiro ) )
            (
            --com_retiro
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'com_retiro' ,ant.com_retiro ,
    nvo.com_retiro )),
        when ((ant.com_consulta != nvo.com_consulta ) )
            (
            --com_consulta
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'com_consulta' ,ant.com_consulta 
    ,nvo.com_consulta )),
        when ((ant.criterio_com != nvo.criterio_com ) )
            (
            --criterio_com
            execute procedure bdinteg@coppelcont_tcp:"informix"
    .sp_tr_llenado_bitacora_ptf(nvo.id_ptf ,'criterio_com' ,ant.criterio_com 
    ,nvo.criterio_com ));

