create trigger "informix".tr_act_estyciud_sucursales insert on 
    "informix".si_ptf referencing new as ptf
    for each row
        when (((ptf.tipo = 'S' ) OR (ptf.tipo = 'A' ) ) )
            (
            update "informix".si_sucursales set "informix".si_sucursales.pais 
    = ptf.cve_pais ,"informix".si_sucursales.estado = ptf.cve_estado ,"informix"
    .si_sucursales.ciudad = ptf.cve_ciudad ,"informix".si_sucursales.d_codigo 
    = ptf.cp  where ((sucursal = ptf.id_ptf ) AND (tipo = ptf.tipo ) ) );
    

